Diego Alvarez: Node snippet (abridged):
```js
// docs: node 429 backoff (full jitter)
const { Redwood } = require('redwood-js');
const client = new Redwood({ apiKey: process.env.REDWOOD_KEY });
async function genWithBackoff(req){
  for(let i=0;i<6;i++){
    try{ return await client.generate(req) }catch(err){
      if(err.status===429){
        const ra = Number(err.headers?.['retry-after']) || (2**i);
        await new Promise(r => setTimeout(r, Math.random() * ra * 1000));
        continue;
      }
      throw err;
    }
  }
}
```
